import{_ as n,o as a,c as e,a2 as p}from"./chunks/framework.BG8d4IEm.js";const b=JSON.parse('{"title":"vscode snippets 插件","description":"","frontmatter":{"tags":["工具","vscode"],"read":8},"headers":[],"relativePath":"posts/2020-08-08-vscode-snippets.md","filePath":"posts/2020-08-08-vscode-snippets.md"}'),l={name:"posts/2020-08-08-vscode-snippets.md"};function o(t,s,c,r,i,d){return a(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="vscode-snippets-插件" tabindex="-1">vscode snippets 插件 <a class="header-anchor" href="#vscode-snippets-插件" aria-label="Permalink to &quot;vscode snippets 插件&quot;">​</a></h1><blockquote><p>讲解如何创建一个 vscode snippets 插件</p></blockquote><h2 id="snippet" tabindex="-1">snippet <a class="header-anchor" href="#snippet" aria-label="Permalink to &quot;snippet&quot;">​</a></h2><p>日常工作中经常会遇到重复的代码片段，IDE 提供了 snippet 来实现代码片段复用，参考 <a href="https://code.visualstudio.com/docs/editor/userdefinedsnippets" target="_blank" rel="noreferrer">vscode snippet 文档</a> 创建代码片段。核心结构为</p><div class="language-json line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#E1E4E8;">{</span></span>
<span class="line"><span style="color:#6A737D;">  // 片段的名称</span></span>
<span class="line"><span style="color:#79B8FF;">  &quot;For Loop&quot;</span><span style="color:#E1E4E8;">: {</span></span>
<span class="line"><span style="color:#6A737D;">    // 触发片段的简写名称  </span></span>
<span class="line"><span style="color:#79B8FF;">    &quot;prefix&quot;</span><span style="color:#E1E4E8;">: [</span><span style="color:#9ECBFF;">&quot;h&quot;</span><span style="color:#E1E4E8;">, </span><span style="color:#9ECBFF;">&quot;h1&quot;</span><span style="color:#E1E4E8;">],</span></span>
<span class="line"><span style="color:#6A737D;">    // 片段内容，</span></span>
<span class="line"><span style="color:#79B8FF;">    &quot;body&quot;</span><span style="color:#E1E4E8;">: [</span><span style="color:#9ECBFF;">&quot;hello world&quot;</span><span style="color:#E1E4E8;">],</span></span>
<span class="line"><span style="color:#6A737D;">    // 片段描述信息，可选</span></span>
<span class="line"><span style="color:#79B8FF;">    &quot;description&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;test snippets&quot;</span></span>
<span class="line"><span style="color:#E1E4E8;">  }</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p><code>body</code> 字段常用语法模式为</p><ol><li><p><code>$1-n</code> tab 占位 ,当输入片段后,利用 <code>tab</code> 键会切换光标到对应占位位置</p><blockquote><p>注意占位符变量只支持数字，<strong>$0</strong> 表示光标最终停留位置</p></blockquote></li><li><p><code>\${n: default}</code> 占位默认值, 当对应占位符未输入内容时会被 default 替换</p></li><li><p><code>\${n:|1,2,3|}</code> 占位选择，切换到对应占位会弹出选择框</p></li><li><p><code>\${name:default}</code> 变量，未定义变量默认为 default</p><blockquote><p>注意由于变量未设置 default 时会默认为空，再使用片段时若想显示 $ 可采用 <code>$$</code> 的方式</p></blockquote></li><li><p>内置变量，例如期望占位内容的默认值为剪切板内容，可使用 <code>$CLIPBOARD</code> ,或者采用 <code>$TM_FILENAME_BASE</code> 来将组件名设置为去掉后缀的文件名，常量列表参见 <a href="https://code.visualstudio.com/docs/editor/userdefinedsnippets#_variables" target="_blank" rel="noreferrer">Variables</a></p></li><li><p>变量转换,例如想提取 <code>$TM_FILENAME</code> 的后缀名，可采用 <code>\${TM_FILENAME/\\(\\\\.\\\\w+)$/$1/}</code> 提取文件后缀名，</p></li></ol><p>其余更详细语法参见 <a href="https://code.visualstudio.com/docs/editor/userdefinedsnippets#_grammar" target="_blank" rel="noreferrer">grammar</a></p><h3 id="片段快捷键" tabindex="-1">片段快捷键 <a class="header-anchor" href="#片段快捷键" aria-label="Permalink to &quot;片段快捷键&quot;">​</a></h3><p>对于反复使用的片段支持快捷键触发，配置格式为</p><div class="language-json line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#E1E4E8;">{</span></span>
<span class="line"><span style="color:#6A737D;">  // 配置对应快捷键</span></span>
<span class="line"><span style="color:#79B8FF;">  &quot;key&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;cmd+k 1&quot;</span><span style="color:#E1E4E8;">,</span></span>
<span class="line"><span style="color:#79B8FF;">  &quot;command&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;editor.action.insertSnippet&quot;</span><span style="color:#E1E4E8;">,</span></span>
<span class="line"><span style="color:#79B8FF;">  &quot;when&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;editorTextFocus&quot;</span><span style="color:#E1E4E8;">,</span></span>
<span class="line"><span style="color:#79B8FF;">  &quot;args&quot;</span><span style="color:#E1E4E8;">: {</span></span>
<span class="line"><span style="color:#6A737D;">     // 快捷键触发的片段 </span></span>
<span class="line"><span style="color:#79B8FF;">    &quot;snippet&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;console.log($1)$0&quot;</span></span>
<span class="line"><span style="color:#E1E4E8;">  }</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>也可将快捷键绑定到申明的代码片段上，修改 <code>args</code> 配置为</p><div class="language-json line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#E1E4E8;">{</span></span>
<span class="line"><span style="color:#6A737D;">  // ...</span></span>
<span class="line"><span style="color:#79B8FF;">  &quot;args&quot;</span><span style="color:#E1E4E8;">: {</span></span>
<span class="line"><span style="color:#79B8FF;">    &quot;langId&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;csharp&quot;</span><span style="color:#E1E4E8;">, </span><span style="color:#6A737D;">// 对应的语言</span></span>
<span class="line"><span style="color:#79B8FF;">    &quot;name&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;myFavSnippet&quot;</span><span style="color:#6A737D;"> // 片段的键名</span></span>
<span class="line"><span style="color:#E1E4E8;">  }</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>详细的语言支持参见 <a href="https://code.visualstudio.com/docs/languages/identifiers" target="_blank" rel="noreferrer">language Identifiers</a></p><h3 id="项目共享片段" tabindex="-1">项目共享片段 <a class="header-anchor" href="#项目共享片段" aria-label="Permalink to &quot;项目共享片段&quot;">​</a></h3><p>可在特定项目创建复用的片段</p><ol><li><p>在项目根目录创建 <code>.vscode</code> 文件夹</p></li><li><p>在 <code>.vscode</code> 文件夹, 添加后缀为 <code>.code-snippets</code> 的文件，例如 <code>test.code-snippets</code></p></li><li><p>在创建的 <code>test.code-snippets</code> 文件中添加片段</p><div class="language-json line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#E1E4E8;">{</span></span>
<span class="line"><span style="color:#79B8FF;">&quot;test&quot;</span><span style="color:#E1E4E8;">: {</span></span>
<span class="line"><span style="color:#79B8FF;">   &quot;prefix&quot;</span><span style="color:#E1E4E8;">: [</span><span style="color:#9ECBFF;">&quot;af&quot;</span><span style="color:#E1E4E8;">, </span><span style="color:#9ECBFF;">&quot;arrowf&quot;</span><span style="color:#E1E4E8;">],</span></span>
<span class="line"><span style="color:#79B8FF;">   &quot;body&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;const \${1:func} = () =&gt; { $0 }&quot;</span><span style="color:#E1E4E8;">,</span></span>
<span class="line"><span style="color:#79B8FF;">   &quot;description&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;arrow function&quot;</span><span style="color:#E1E4E8;">,</span></span>
<span class="line"><span style="color:#6A737D;">   // 此处申明对应作用范围</span></span>
<span class="line"><span style="color:#79B8FF;">   &quot;scope&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;javascript,typescript&quot;</span></span>
<span class="line"><span style="color:#E1E4E8;">   }</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div></li><li><p>项目中即可使用该片段</p></li></ol><p>该功能在版本 1.28 出现，详见 <a href="https://code.visualstudio.com/updates/v1_28#_project-level-snippets" target="_blank" rel="noreferrer">project snippets</a></p><h2 id="vscode-snippet-插件" tabindex="-1">vscode snippet 插件 <a class="header-anchor" href="#vscode-snippet-插件" aria-label="Permalink to &quot;vscode snippet 插件&quot;">​</a></h2><p>除了本地和项目中配置 snippet,可将 snippet 制作为插件进行分享。 参考 <a href="https://code.visualstudio.com/api/language-extensions/snippet-guide" target="_blank" rel="noreferrer">snippet guide</a></p><ol><li>在 package.json 中申明插件路径</li></ol><div class="language-json line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#E1E4E8;">{</span></span>
<span class="line"><span style="color:#79B8FF;">   &quot;contributes&quot;</span><span style="color:#E1E4E8;">: {</span></span>
<span class="line"><span style="color:#79B8FF;">     &quot;snippets&quot;</span><span style="color:#E1E4E8;">: [</span></span>
<span class="line"><span style="color:#E1E4E8;">       {</span></span>
<span class="line"><span style="color:#79B8FF;">         &quot;language&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;javascript&quot;</span><span style="color:#E1E4E8;">,</span></span>
<span class="line"><span style="color:#6A737D;">         // 这里统一放在 snippets 目录方便组织</span></span>
<span class="line"><span style="color:#79B8FF;">         &quot;path&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;./snippets/a.json&quot;</span></span>
<span class="line"><span style="color:#E1E4E8;">       }</span></span>
<span class="line"><span style="color:#E1E4E8;">     ]</span></span>
<span class="line"><span style="color:#E1E4E8;">   }</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><ol start="2"><li>在 <code>snippets</code> 目录创建 <code>a.json</code> 的 snippet</li></ol><p>然后将整个项目拷贝到 <code>~/.vscode/extensions</code> ,重启 vscode 即可触发插件的 snippet</p><h3 id="本地打包和安装" tabindex="-1">本地打包和安装 <a class="header-anchor" href="#本地打包和安装" aria-label="Permalink to &quot;本地打包和安装&quot;">​</a></h3><p>采用 vsce 将应用打包为 <code>.vsix</code> 文件，其他可采用 vscode 提供的 cli <code>code</code> 命令进行安装，开启 code 命令详见 <a href="http://blog.zenheart.site/posts/2018-08-28-vscode.html#%E9%85%8D%E7%BD%AE-code-%E5%91%BD%E4%BB%A4" target="_blank" rel="noreferrer">配置 code 命令</a></p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># 1. 全局安装 vsce</span></span>
<span class="line"><span style="color:#B392F0;">npm</span><span style="color:#9ECBFF;"> install</span><span style="color:#79B8FF;"> -g</span><span style="color:#9ECBFF;"> vsce</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;"># 2. 项目更目录打包插件</span></span>
<span class="line"><span style="color:#B392F0;">vsce</span><span style="color:#9ECBFF;"> package</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;"># 3. 使用 code 安装 .vsix 文件</span></span>
<span class="line"><span style="color:#B392F0;">code</span><span style="color:#79B8FF;"> --install-extension</span><span style="color:#9ECBFF;"> my-extension-0.0.1.vsix</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h3 id="发布" tabindex="-1">发布 <a class="header-anchor" href="#发布" aria-label="Permalink to &quot;发布&quot;">​</a></h3><p>发布详见 <a href="https://code.visualstudio.com/api/working-with-extensions/publishing-extension" target="_blank" rel="noreferrer">Publishing Extensions</a> 流程类似 npm 包发布</p><h2 id="snippets-模板扩展" tabindex="-1">snippets 模板扩展 <a class="header-anchor" href="#snippets-模板扩展" aria-label="Permalink to &quot;snippets 模板扩展&quot;">​</a></h2><p>由于 vscode snippets 不支持模板文件，单书写片段过于庞大时， 需要将模板内容转换为 snippet <code>body</code> 字段的数组模式。为了简化类似 snippet 的书写流程，可以在 <code>body</code> 中配置模板文件路径。然后利用 js 脚本读取路径中的文件内容转换为数组，重新保存即可简化包含大量内容的片段书写</p>`,31)])])}const E=n(l,[["render",o]]);export{b as __pageData,E as default};
